SELECT CAST(COUNT(DISTINCT CASE WHEN a.readmit_30d THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS readmission_rate, AVG(CASE WHEN a.readmit_30d THEN a.los END) AS avg_los_30d, AVG(CASE WHEN NOT a.readmit_30d THEN a.los END) AS avg_los_not_30d, COUNT(DISTINCT CASE WHEN a.los > 9 THEN a.subject_id END) * 100.0 / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS pct_stays_gt_9d FROM (SELECT s.subject_id, a.hadm_id, a.admittime, a.dischtime, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, s.insurance, a.admission_type, a.discharge_location, a.edregtime, a.edouttime, s.dod, (a.discharge_location = 'ED' AND a.edregtime BETWEEN a.admittime AND a.dischtime AND p.anchor_age BETWEEN 51 AND 61 AND p.gender = 'M' AND p.anchor_year_group = 'Principal acute pancreatitis' AND s.insurance = 'Medicare') AS readmit_30d, (a.discharge_location = 'ED' AND a.edregtime BETWEEN a.admittime AND a.dischtime AND p.anchor_age BETWEEN 51 AND 61 AND p.gender = 'M' AND p.anchor_year_group = 'Principal acute pancreatitis' AND s.insurance = 'Medicare') AS readmit_anyd, (a.discharge_location = 'ED' AND a.edregtime BETWEEN a.admittime AND a.dischtime AND p.anchor_age BETWEEN 51 AND 61 AND p.gender = 'M' AND p.anchor_year_group = 'Principal acute pancreatitis' AND s.insurance = 'Medicare') AS readmit_within_30d, (a.discharge_location = 'ED' AND a.edregtime BETWEEN a.admittime AND a.dischtime AND p.anchor_age BETWEEN 51 AND 61 AND p.gender = 'M' AND p.anchor_year_group = 'Principal acute pancreatitis' AND s.insurance = 'Medicare') AS readmit_within_90d, (a.discharge_location = 'ED' AND a.edregtime BETWEEN a.admittime AND a.dischtime AND p.anchor_age BETWEEN 51 AND 61 AND p.gender = 'M' AND p.anchor_year_group = 'Principal acute pancreatitis' AND s.insurance = 'Medicare') AS readmit_within_180d, (a.discharge_location = 'ED' AND a.edregtime BETWEEN a.admittime AND a.dischtime AND p.anchor_age BETWEEN 51 AND 61 AND p.gender = 'M' AND p.anchor_year_group = 'Principal acute pancreatitis' AND s.insurance = 'Medicare') AS readmit_within_365d, (a.discharge_location = 'ED' AND a.edregtime BETWEEN a.admittime AND a.dischtime AND p.anchor_age BETWEEN 51 AND 61 AND p.gender = 'M' AND p.anchor_year_group = 'Principal acute pancreatitis' AND s.insurance = 'Medicare') AS readmit_within_730d, (a.discharge_location = 'ED' AND a.edregtime BETWEEN a.admittime AND a.dischtime AND p.anchor_age BETWEEN 51 AND 61 AND p.gender = 'M' AND p.anchor_;